function validate([squares]) {
  if (squares.length < 1 || squares.length > 50000) return 'squares needs 1 to 5 * 10^4 squares.';
  let total = 0;
  for (const square of squares) {
    if (square.length !== 3) return 'Each square is [x, y, l].';
    const [x, y, l] = square;
    if (x < 0 || x > 1000000000 || y < 0 || y > 1000000000) return 'x and y are between 0 and 10^9.';
    if (l < 1 || l > 1000000000) return 'Each side length is between 1 and 10^9.';
    total += l * l;
  }
  if (total > 1000000000000) return 'The total area of the squares is at most 10^12.';
  return null;
}

