function separateSquares(squares) {
  let total = 0;
  let low = Infinity;
  let high = 0;
  for (const [, y, side] of squares) {
    total += side * side;
    low = Math.min(low, y);
    high = Math.max(high, y + side);
  }

  const areaBelow = (line) => {
    let area = 0;
    for (const [, y, side] of squares) {
      area += side * Math.min(side, Math.max(0, line - y));
    }
    return area;
  };

  while (high - low > 1e-6) {
    const mid = (low + high) / 2;
    if (2 * areaBelow(mid) >= total) {
      high = mid;
    } else {
      low = mid;
    }
  }
  return high;
}

