function separateSquares(squares) {
  // Between two consecutive horizontal edges no square starts or ends, so the area below the line grows
  // linearly there: find the first edge with at least half of the area below it and interpolate.
  const below = (h) => {
    let sum = 0;
    for (const [, y, l] of squares) {
      if (y + l <= h) sum += l * l;
      else if (y < h) sum += l * (h - y);
    }
    return sum;
  };
  let total = 0;
  for (const [, , l] of squares) total += l * l;
  const edges = [...new Set(squares.flatMap(([, y, l]) => [y, y + l]))].sort((a, b) => a - b);
  for (let k = 1; k < edges.length; k++) {
    const a = edges[k - 1], b = edges[k], atA = below(a), atB = below(b);
    if (2 * atB >= total) return a + (total / 2 - atA) / (atB - atA) * (b - a);
  }
  return edges[edges.length - 1];
}

