function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    // 2,000 squares with sides up to 22,000 keep the total area under 10^12.
    const top = rand() < 0.5 ? 1000000000 : int(1000, 100000);
    return [Array.from({ length: 2000 }, () => [int(0, 1000000000), int(0, top), int(1, 22000)])];
  }
  const mode = rand();
  if (mode < 0.2) {
    // Two groups with equal area and a gap between them: the answer is the top of the lower group.
    const sides = Array.from({ length: int(1, 2) }, () => int(1, 3));
    const lower = sides.map(l => [int(0, 5), int(0, 2), l]);
    const roof = Math.max(...lower.map(([, y, l]) => y + l));
    const lift = roof + int(0, 3);
    return [[...lower, ...sides.map(l => [int(0, 5), lift + int(0, 2), l])]];
  }
  const n = int(1, 5), reach = int(2, 10);
  // Some inputs scale everything up or lift it near 10^9, keeping the shape but testing large values.
  const scale = mode < 0.35 ? 100000 : 1, lift = mode >= 0.35 && mode < 0.5 ? 999999000 : 0;
  return [Array.from({ length: n }, () => [int(0, reach) * scale, int(0, reach) * scale + lift, int(1, 4) * scale])];
}
